import React, {useEffect} from 'react'
import s from './HW12.module.css'
import s2 from '../../s1-main/App.module.css'
import SuperSelect from '../hw07/common/c5-SuperSelect/SuperSelect'
import {useDispatch, useSelector} from 'react-redux'
import {changeThemeId} from './bll/themeReducer'
import {AppStoreType} from '../hw10/bll/store'

const themes = [
    { id: 1, value: 'light' },
    { id: 2, value: 'blue' },
    { id: 3, value: 'dark' },
]

const HW12 = () => {
    const dispatch = useDispatch()
    const themeId = useSelector((state: AppStoreType) => state.theme.themeId)

    const change = (id: number) => {
        dispatch(changeThemeId(id))
    }

    useEffect(() => {
        const html = document.documentElement;
        html.dataset.theme = themeId.toString();

        // Встановлюємо колір фону для всіх тем
        if (themeId === 1) {
            html.style.backgroundColor = 'rgb(255, 255, 255)';
        } else if (themeId === 2) {
            html.style.backgroundColor = 'rgb(221, 238, 255)'; // колір для blue теми
        } else if (themeId === 3) {
            html.style.backgroundColor = 'rgb(33, 42, 52)'; // колір для dark теми
        }
    }, [themeId]);

    return (
        <div id={'hw12'} className={s.hw12}>
            <div id={'hw12-text'} className={`${s2.hwTitle} ${s.hwTitle}`}>
                Homework #12
            </div>

            <div className={s.hwContainer}>
                <SuperSelect
                    id={'hw12-select-theme'}
                    className={s.select}
                    options={themes}
                    value={themeId}
                    onChangeOption={change}
                />
            </div>
        </div>
    )
}

export default HW12