// types
type InitStateType = {
    themeId: number
}

type ChangeThemeActionType = {
    type: 'SET_THEME_ID'
    id: number
}

const initState: InitStateType = {
    themeId: 1,
}

export const themeReducer = (state = initState, action: ChangeThemeActionType): InitStateType => {
    switch (action.type) {
        case 'SET_THEME_ID':
            return { ...state, themeId: action.id }
        default:
            return state
    }
}

export const changeThemeId = (id: number): ChangeThemeActionType => ({ type: 'SET_THEME_ID', id })
